steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query {
      issues(first: 50, filter: { title: { contains: \"login timeout\" } }) {
        nodes {
          id
          identifier
          title
          priority
          createdAt
          creator {
            name
            email
          }
        }
      }
    }"
  }'
